package org.apache.commons.lang3;
public class ArrayUtils {
    public static void reverseArray(char[] a) { if(a==null) return; int len = a.length; for(int i=0; i<len/2; i++) { char t = a[i]; a[i] = a[len-1-i]; a[len-1-i] = t; } }
}

package org.apache.commons.lang3;
public class StringFormatter {
    public static String toFirstUpper(String in) { if(in==null) return null; return Character.toUpperCase(in.charAt(0)) + in.substring(1); }
    public static String removeAccents(String s) { return java.text.Normalizer.normalize(s, java.text.Normalizer.Form.NFD).replaceAll("\\p{M}", ""); }
}

package org.apache.commons.lang3;
public class StringUtils {
    public static String capitalize(String s) { return StringFormatter.toFirstUpper(s); }
    public static boolean isBlank(CharSequence cs) { return StringValidator.checkBlank(cs); }
    public static String reverse(String s) { char[] a = s.toCharArray(); ArrayUtils.reverseArray(a); return new String(a); }
    public static String wrap(String s, int w) { return TextWrapper.wrap(s, w); }
    public static boolean isNumeric(String s) { return NumberUtils.isParsable(s); }
    public static String stripAccents(String s) { return StringFormatter.removeAccents(s); }
}

package org.apache.commons.lang3;
public class StringValidator {
    public static boolean checkBlank(CharSequence cs) { return cs == null || cs.toString().trim().isEmpty(); }
    public static boolean isAlpha(String s) { return s != null && s.chars().allMatch(Character::isLetter); }
    public static boolean isPalindrome(String s) { if(s==null) return false; String r = new StringBuilder(s).reverse().toString(); return s.equalsIgnoreCase(r); }
}

package org.apache.commons.lang3;
public class TextWrapper {
    public static String wrap(String str, int w) { if(str==null) return null; if(w < 1) return str; return str.length() > w ? str.substring(0,w) + "\n" + str.substring(w) : str; }
}
